#!/usr/bin/env python3
"""Rebuild the winter contribution. Editorial data explicit; no network or shared-file mutations."""
from pathlib import Path
import json,csv,re,collections
OUT=Path(__file__).resolve().parent
talks=[];items=[];problems=[];corrections=[];bib={}
def save():
    for name,obj in [('talks',talks),('items',items),('problems',problems)]:
        (OUT/(name+'.json')).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    (OUT/'references.bib').write_text('\n\n'.join(bib.values())+'\n')
    with (OUT/'corrections.csv').open('w',newline='') as f:
        w=csv.writer(f);w.writerow(['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writerows(corrections)
def R(key,author,title,year,url,**kw):
    typ=kw.pop('typ','article');d={'author':author,'title':title,'year':year,**kw,'url':url,'note':'verified'}
    bib[key]='@'+typ+'{'+key+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in d.items())+'\n}'
def T(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary));save()
def I(record,n,pages,kind,title,notes,statement,cl,fate,status,refs=(),reconstruction=r'',literal='correct with missing hypotheses',match='exact',verification='read the result',confidence='high',problem='',worth='',speaker=None):
    kind={'example':'remark','programme':'remark','principle':'remark','counterexample':'construction'}.get(kind,kind)
    d=dict(id=f'1964-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status='As of November 2026, '+status,literal_correctness=literal,publication_match=match,verification=verification,development='annotated',problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker:d['speaker']=speaker
    items.append(d);save()
def F(r,n,p,k,t,notes,missing,search='',speaker=None):
    I(r,n,p,k,t,notes,'No unique mathematical statement can be extracted: '+missing,'F',search or 'No uniquely delimited theorem or problem is specified, so no publication is assigned.','the fragment remains unidentifiable from the supplied evidence; this does not establish that a mathematical problem is open.',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',speaker=speaker)
def C(page,place,old,new,evidence,applies='both',typ='faithful_error'):
    corrections.append([page,place,old,new,evidence,applies,typ]);save()

